    Bug 2010296 - Migrate remaining XUL checked/disabled attributes to html-style boolean attributes. r=vineet

    Differential Revision: https://phabricator.services.mozilla.com/D278987

diff --git a/mail/base/content/mailWindowOverlay.js b/mail/base/content/mailWindowOverlay.js
index 7954baa5458..9e191821d00 100644
--- a/mail/base/content/mailWindowOverlay.js
+++ b/mail/base/content/mailWindowOverlay.js
@@ -548,7 +548,7 @@ function InitViewMessagesMenu() {

   document
     .getElementById("viewAllMessagesMenuItem")
-    .setAttribute(
+    .toggleAttribute(
       "checked",
       !viewWrapper || (!viewWrapper.showUnreadOnly && !viewWrapper.specialView)
     );
diff --git a/mail/base/content/tabmail.js b/mail/base/content/tabmail.js
index 5e2066646b1..431d5a36517 100644
--- a/mail/base/content/tabmail.js
+++ b/mail/base/content/tabmail.js
@@ -1997,11 +1997,11 @@ window.addEventListener(
       }

       currentTabInfo = tabmail.tabInfo.find(info => info.tabNode == tabNode);
-      openInWindowItem.setAttribute(
+      openInWindowItem.toggleAttribute(
         "disabled",
         currentTabInfo.canClose && tabmail.persistTab(currentTabInfo)
       );
-      closeOtherTabsItem.setAttribute(
+      closeOtherTabsItem.toggleAttribute(
         "disabled",
         tabmail.tabInfo.every(info => info == currentTabInfo || !info.canClose)
       );
diff --git a/mailnews/base/prefs/content/am-server.js b/mailnews/base/prefs/content/am-server.js
index 7b3edfa39b2..81a5c776e8d 100644
--- a/mailnews/base/prefs/content/am-server.js
+++ b/mailnews/base/prefs/content/am-server.js
@@ -121,11 +121,12 @@ function onInit(aPageId, aServerId) {
   );
   storeTypeElement.selectedItem = targetItem[0];
   // Disable store type change if store has not been used yet.
-  storeTypeElement.setAttribute(
+  storeTypeElement.toggleAttribute(
     "disabled",
-    gServer.getBoolValue("canChangeStoreType")
-      ? "false"
-      : !Services.prefs.getBoolPref("mail.store_conversion_enabled")
+    !(
+      gServer.getBoolValue("canChangeStoreType") ||
+      Services.prefs.getBoolPref("mail.store_conversion_enabled")
+    )
   );
   // Initialise 'gOriginalStoreType' to the item that was originally selected.
   gOriginalStoreType = storeTypeElement.value;
diff --git a/mailnews/base/prefs/content/am-serverwithnoidentities.js b/mailnews/base/prefs/content/am-serverwithnoidentities.js
index 2e30f63671f..d5ac76f9910 100644
--- a/mailnews/base/prefs/content/am-serverwithnoidentities.js
+++ b/mailnews/base/prefs/content/am-serverwithnoidentities.js
@@ -79,11 +79,12 @@ function onInit() {
   );
   storeTypeElement.selectedItem = targetItem[0];
   // Disable store type change if store has not been used yet.
-  storeTypeElement.setAttribute(
+  storeTypeElement.toggleAttribute(
     "disabled",
-    gAccount.incomingServer.getBoolValue("canChangeStoreType")
-      ? "false"
-      : !Services.prefs.getBoolPref("mail.store_conversion_enabled")
+    !(
+      gAccount.getBoolValue("canChangeStoreType") ||
+      Services.prefs.getBoolPref("mail.store_conversion_enabled")
+    )
   );
   // Initialise 'gOriginalStoreType' to the item that was originally selected.
   gOriginalStoreType = storeTypeElement.value;
